using System;
using System.Collections.Generic;
using RimWorld;
using Verse;
using Verse.Grammar;

namespace Duelo
{
    /// <summary>
    /// Writes a short eulogy from a pawn's real life: records, tales, relations, traits, best skill,
    /// and how they died. Every line is generated by Duelo_RulePack_Eulogy so the wording varies.
    /// </summary>
    public static class EulogyComposer
    {
        public const int MaxMiddleLines = 4;
        public const int MissedByMinOpinion = 20;
        public const int SkillMinLevel = 8;

        enum Part { Deed = 0, Self = 1, People = 2 }

        sealed class Fact
        {
            public string symbol;
            public float weight;
            public Part part;
            public bool life;          // a deed or a bond, as opposed to a personality line
            public float sortKey;
            public readonly List<Rule> rules = new List<Rule>();
        }

        // Exposed for tests and debugging: what the last composition used.
        public static readonly List<string> LastSymbols = new List<string>();

        /// <summary>Eulogies are written for humanlikes of the player faction (colonists and slaves).</summary>
        public static bool Qualifies(Pawn p)
        {
            return p != null && p.RaceProps != null && p.RaceProps.Humanlike && p.Faction != null && p.Faction.IsPlayer;
        }

        public static EulogyRecord ComposeRecord(Pawn p, DamageInfo? dinfo, Hediff culprit, bool causeKnown)
        {
            // Own seed: writing a eulogy must not shift the game's random sequence.
            Rand.PushState(Gen.HashCombineInt(p.thingIDNumber, Find.TickManager.TicksGame));
            try
            {
                return new EulogyRecord
                {
                    pawnId = p.ThingID,
                    pawnName = p.LabelShortCap,
                    deathTick = Find.TickManager.TicksGame,
                    lines = Compose(p, dinfo, culprit, causeKnown),
                };
            }
            finally
            {
                Rand.PopState();
            }
        }

        /// <summary>Every fact the composer found for this pawn, before selection (for tests and debugging).</summary>
        public static List<string> CandidateSymbols(Pawn p, out string opening)
        {
            var result = new List<string>();
            foreach (Fact f in Gather(p, out opening)) result.Add(f.symbol);
            return result;
        }

        static List<Fact> Gather(Pawn p, out string opening)
        {
            var facts = new List<Fact>();
            opening = "eulogy_open";
            SkillDef mastered = null;
            var mentioned = new HashSet<Pawn>();

            List<Tale> tales = Find.TaleManager?.AllTalesListForReading;
            if (tales != null)
            {
                var usedSymbols = new HashSet<string>();
                for (int i = tales.Count - 1; i >= 0; i--)   // newest first
                {
                    Tale t = tales[i];
                    try
                    {
                        if (t?.def != null && t.Concerns(p))
                            AddTale(t, p, facts, usedSymbols, mentioned, ref opening, ref mastered);
                    }
                    catch (Exception e)
                    {
                        Log.ErrorOnce("[Duelo] eulogy: could not read tale " + t?.def?.defName + ": " + e, 0x5D0E1 ^ (t?.id ?? 0));
                    }
                }
            }

            AddRecords(p, facts);
            AddSelf(p, facts, mastered);
            AddPeople(p, facts, mentioned);
            return facts;
        }

        public static List<string> Compose(Pawn p, DamageInfo? dinfo, Hediff culprit, bool causeKnown)
        {
            LastSymbols.Clear();
            List<Fact> facts = Gather(p, out string opening);

            var lines = new List<string>();
            bool anyLife = false;
            for (int i = 0; i < facts.Count; i++) anyLife |= facts[i].life;

            if (!anyLife)
            {
                lines.Add(Resolve("eulogy_sad", p, null));
                return lines;
            }

            var openRules = new List<Rule> { new Rule_String("DURATION", Duration(p)) };
            lines.Add(Resolve(opening, p, openRules));

            for (int i = 0; i < facts.Count; i++) facts[i].sortKey = facts[i].weight * Rand.Range(0.8f, 1.25f);
            facts.Sort((a, b) => b.sortKey.CompareTo(a.sortKey));
            if (facts.Count > MaxMiddleLines) facts.RemoveRange(MaxMiddleLines, facts.Count - MaxMiddleLines);
            // deeds, then who they were, then the people they leave
            facts.Sort((a, b) => a.part != b.part ? a.part.CompareTo(b.part) : b.weight.CompareTo(a.weight));
            for (int i = 0; i < facts.Count; i++) lines.Add(Resolve(facts[i].symbol, p, facts[i].rules));

            lines.Add(DeathLine(p, dinfo, culprit, causeKnown));
            return lines;
        }

        static string Duration(Pawn p)
        {
            int ticks = p.records != null ? p.records.GetAsInt(RecordDefOf.TimeAsColonistOrColonyAnimal) : 0;
            if (ticks < GenDate.TicksPerDay) return "LessThanADay".Translate();
            return ticks.ToStringTicksToPeriod(allowSeconds: false, shortForm: false, canUseDecimals: true);
        }

        // ---------------------------------------------------------------- tales

        static void AddTale(Tale t, Pawn p, List<Fact> facts, HashSet<string> used, HashSet<Pawn> mentioned, ref string opening, ref SkillDef mastered)
        {
            string dn = t.def.defName;
            if (t is Tale_DoublePawn dp)
            {
                bool first = dp.firstPawnData?.pawn == p;
                bool second = dp.secondPawnData?.pawn == p;
                if (!first && !second) return;
                TaleData_Pawn other = first ? dp.secondPawnData : dp.firstPawnData;
                if (other == null) return;
                switch (dn)
                {
                    case "Marriage": AddTaleFact(facts, used, mentioned, "eulogy_tale_Marriage", 9f, Part.People, other); break;
                    case "BecameLover": AddTaleFact(facts, used, mentioned, "eulogy_tale_BecameLover", 6f, Part.People, other); break;
                    case "KilledMajorThreat": if (first) AddTaleFact(facts, used, mentioned, "eulogy_tale_KilledMajorThreat", 8f, Part.Deed, other); break;
                    case "BondedWithAnimal": if (first) AddTaleFact(facts, used, mentioned, "eulogy_tale_BondedWithAnimal", 6f, Part.People, other); break;
                    case "GaveBirth": if (first) AddTaleFact(facts, used, mentioned, "eulogy_tale_GaveBirth", 7f, Part.People, other); break;
                    case "BuriedCorpse":
                        if (first && other.everBeenColonistOrTameAnimal && other.pawn != p)
                            AddTaleFact(facts, used, mentioned, "eulogy_tale_BuriedCorpse", 5f, Part.Deed, other);
                        break;
                    case "SocialFight": AddTaleFact(facts, used, mentioned, "eulogy_tale_SocialFight", 3f, Part.People, other); break;
                    case "Captured": if (first) AddTaleFact(facts, used, mentioned, "eulogy_tale_Captured", 3f, Part.Deed, other); break;
                    case "Recruited":
                        if (first) AddTaleFact(facts, used, mentioned, "eulogy_tale_Recruited", 5f, Part.People, other);
                        else opening = "eulogy_open_recruited";
                        break;
                }
                return;
            }
            if (t is Tale_SinglePawnAndThing st)
            {
                if (dn == "CraftedArt" && st.pawnData?.pawn == p && st.thingData != null && !st.thingData.title.NullOrEmpty() && used.Add("eulogy_tale_CraftedArt"))
                {
                    var f = new Fact { symbol = "eulogy_tale_CraftedArt", weight = 6f, part = Part.Deed, life = true };
                    f.rules.Add(new Rule_String("ART", st.thingData.title));
                    facts.Add(f);
                }
                return;
            }
            if (t is Tale_SinglePawnAndDef sd)
            {
                if ((dn == "GainedMasterSkillWithPassion" || dn == "GainedMasterSkillWithoutPassion") && sd.pawnData?.pawn == p
                    && sd.defData?.def is SkillDef skill && used.Add("eulogy_tale_Mastered"))
                {
                    var f = new Fact { symbol = "eulogy_tale_Mastered", weight = 6f, part = Part.Self, life = true };
                    f.rules.Add(new Rule_String("SKILL", skill.label));
                    facts.Add(f);
                    mastered = skill;
                }
                return;
            }
            if (t is Tale_SinglePawn s && dn == "LandedInPod" && s.pawnData?.pawn == p && opening == "eulogy_open")
                opening = "eulogy_open_pod";
        }

        static void AddTaleFact(List<Fact> facts, HashSet<string> used, HashSet<Pawn> mentioned, string symbol, float weight, Part part, TaleData_Pawn other)
        {
            if (!used.Add(symbol)) return;   // newest tale of each kind only
            var f = new Fact { symbol = symbol, weight = weight, part = part, life = true };
            f.rules.AddRange(other.GetRules("OTHER"));
            facts.Add(f);
            if (other.pawn != null) mentioned.Add(other.pawn);
        }

        // ---------------------------------------------------------------- records

        static void AddRecords(Pawn p, List<Fact> facts)
        {
            Pawn_RecordsTracker r = p.records;
            if (r == null) return;
            int kills = r.GetAsInt(RecordDefOf.KillsHumanlikes) + r.GetAsInt(RecordDefOf.KillsMechanoids);
            if (RecordDefOf.KillsEntities != null) kills += r.GetAsInt(RecordDefOf.KillsEntities);
            AddCount(facts, "eulogy_kills", kills, 3, 4f + Math.Min(kills, 40) / 5f);

            int ops = r.GetAsInt(RecordDefOf.OperationsPerformed);
            AddCount(facts, "eulogy_surgeon", ops, 3, 5f + Math.Min(ops, 30) / 6f);
            if (ops < 3) AddCount(facts, "eulogy_tender", r.GetAsInt(RecordDefOf.TimesTendedOther), 15, 4f);
            AddCount(facts, "eulogy_crafter", r.GetAsInt(RecordDefOf.ThingsCrafted), 15, 4f);
            AddCount(facts, "eulogy_builder", r.GetAsInt(RecordDefOf.ThingsConstructed), 25, 4f);
            AddCount(facts, "eulogy_cook", r.GetAsInt(RecordDefOf.MealsCooked), 40, 4f);
            AddCount(facts, "eulogy_farmer", r.GetAsInt(RecordDefOf.PlantsHarvested), 60, 3f);
            AddCount(facts, "eulogy_tamer", r.GetAsInt(RecordDefOf.AnimalsTamed), 2, 4f);
            AddCount(facts, "eulogy_recruiter", r.GetAsInt(RecordDefOf.PrisonersRecruited), 1, 5f);
            AddCount(facts, "eulogy_miner", r.GetAsInt(RecordDefOf.CellsMined), 150, 3f);
            if (r.GetValue(RecordDefOf.ResearchPointsResearched) >= 3000f)
                facts.Add(new Fact { symbol = "eulogy_researcher", weight = 4f, part = Part.Deed, life = true });
        }

        static void AddCount(List<Fact> facts, string symbol, int count, int min, float weight)
        {
            if (count < min) return;
            var f = new Fact { symbol = symbol, weight = weight, part = Part.Deed, life = true };
            f.rules.Add(new Rule_String("COUNT", count.ToString()));
            facts.Add(f);
        }

        // ---------------------------------------------------------------- personality

        static void AddSelf(Pawn p, List<Fact> facts, SkillDef mastered)
        {
            if (p.skills != null)
            {
                SkillRecord best = null;
                List<SkillRecord> skills = p.skills.skills;
                for (int i = 0; i < skills.Count; i++)
                    if (!skills[i].TotallyDisabled && (best == null || skills[i].Level > best.Level)) best = skills[i];
                if (best != null && best.Level >= SkillMinLevel && best.def != mastered)
                {
                    var f = new Fact { symbol = "eulogy_skill", weight = 3f + (best.Level - SkillMinLevel) / 2f, part = Part.Self };
                    f.rules.Add(new Rule_String("SKILL", best.def.label));
                    facts.Add(f);
                }
            }
            if (p.story?.traits != null)
            {
                var visible = new List<Trait>();
                foreach (Trait tr in p.story.traits.allTraits)
                    if (tr != null && !tr.Suppressed && !tr.Label.NullOrEmpty()) visible.Add(tr);
                if (visible.Count > 0)
                {
                    var f = new Fact { symbol = "eulogy_trait", weight = 3.5f, part = Part.Self };
                    f.rules.Add(new Rule_String("TRAIT", visible.RandomElement().Label.ToLower()));
                    facts.Add(f);
                }
            }
        }

        // ---------------------------------------------------------------- relations

        static void AddPeople(Pawn p, List<Fact> facts, HashSet<Pawn> mentioned)
        {
            if (p.relations == null) return;

            Pawn partner = null;
            int partnerRank = 0;
            foreach (DirectPawnRelation rel in p.relations.DirectRelations)
            {
                int rank = rel.def == PawnRelationDefOf.Spouse ? 3 : rel.def == PawnRelationDefOf.Fiance ? 2 : rel.def == PawnRelationDefOf.Lover ? 1 : 0;
                if (rank > partnerRank && rel.otherPawn != null) { partner = rel.otherPawn; partnerRank = rank; }
            }
            if (partner != null && !mentioned.Contains(partner))
            {
                var f = new Fact { symbol = partner.Dead ? "eulogy_partner_dead" : "eulogy_partner", weight = 7f, part = Part.People, life = true };
                f.rules.AddRange(GrammarUtility.RulesForPawn("OTHER", partner));
                facts.Add(f);
                mentioned.Add(partner);
            }

            int children = 0;
            foreach (Pawn c in p.relations.Children)
                if (c != null && !c.Dead) children++;
            if (children == 1)
                facts.Add(new Fact { symbol = "eulogy_child", weight = 5f, part = Part.People, life = true });
            else if (children > 1)
            {
                var f = new Fact { symbol = "eulogy_children", weight = 5.5f, part = Part.People, life = true };
                f.rules.Add(new Rule_String("COUNT", children.ToString()));
                facts.Add(f);
            }

            Pawn missedBy = null;
            int bestOpinion = MissedByMinOpinion - 1;
            // copy: OpinionOf runs thought workers that may use PawnsFinder's shared result lists
            var living = new List<Pawn>(PawnsFinder.AllMapsCaravansAndTravellingTransporters_Alive_FreeColonists);
            for (int i = 0; i < living.Count; i++)
            {
                Pawn other = living[i];
                if (other == p || other.relations == null || mentioned.Contains(other) || !other.RaceProps.Humanlike) continue;
                int op = SafeOpinion(other, p);
                if (op > bestOpinion) { bestOpinion = op; missedBy = other; }
            }
            if (missedBy != null)
            {
                var f = new Fact { symbol = "eulogy_missed", weight = 6f, part = Part.People, life = true };
                f.rules.AddRange(GrammarUtility.RulesForPawn("OTHER", missedBy));
                facts.Add(f);
            }
        }

        /// <summary>OpinionOf a dead pawn runs every situational thought worker; a modded one may not expect that.</summary>
        public static int SafeOpinion(Pawn of, Pawn about)
        {
            try { return of.relations.OpinionOf(about); }
            catch (Exception e)
            {
                Log.ErrorOnce("[Duelo] OpinionOf failed for " + of + " about " + about + ": " + e, 0x5D0E2);
                return 0;
            }
        }

        // ---------------------------------------------------------------- death

        static string DeathLine(Pawn p, DamageInfo? dinfo, Hediff culprit, bool causeKnown)
        {
            var rules = new List<Rule>();
            string symbol;
            if (!causeKnown)
                symbol = "eulogy_death_unknown";
            else if (dinfo.HasValue && dinfo.Value.Instigator is Pawn killer && killer != p)
            {
                rules.AddRange(GrammarUtility.RulesForPawn("KILLER", killer));
                if (killer.RaceProps.Humanlike)
                    symbol = killer.Faction != null && !killer.Faction.IsPlayer && !killer.Faction.Name.NullOrEmpty()
                        ? "eulogy_death_person" : "eulogy_death_person_nofaction";
                else
                    symbol = "eulogy_death_beast";
            }
            else if (culprit != null)
            {
                symbol = "eulogy_death_illness";
                rules.Add(new Rule_String("CAUSE", culprit.def.label));
            }
            else if (dinfo.HasValue)
                symbol = "eulogy_death_accident";
            else
                symbol = "eulogy_death_unknown";
            return Resolve(symbol, p, rules);
        }

        // ---------------------------------------------------------------- grammar

        static string Resolve(string symbol, Pawn p, List<Rule> extra)
        {
            LastSymbols.Add(symbol);
            var req = new GrammarRequest();
            req.Includes.Add(DueloDefOf.Duelo_RulePack_Eulogy);
            req.Rules.AddRange(GrammarUtility.RulesForPawn("PAWN", p, req.Constants));
            if (extra != null) req.Rules.AddRange(extra);
            return GrammarResolver.Resolve(symbol, req, "Duelo eulogy " + symbol).StripTags();
        }
    }
}
